window.kbPageData["views/entry/k-b04cf0c4881c60de"] = {"key":"entry/k-b04cf0c4881c60de","state":{"route":"entry/k-b04cf0c4881c60de"},"node":{"id":"k-b04cf0c4881c60de","mode":"k","title":"新时代立德树人工程","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#69"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["modern"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["公共管理","政治理论"],"来源主题":["年度政府工作"],"资料类别":["政治理论专项","时政"]},"directorySummary":"新时代立德树人工程是落实立德树人根本任务的教育部署。《加快建设教育强国》提出，坚持不懈用新时代中国特色社会主义思想铸魂育人，推动思政课建设与党的创新理论武装同步推进。","review":{"definition":"新时代立德树人工程是落实立德树人根本任务的教育部署。《加快建设教育强国》提出，坚持不懈用新时代中国特色社会主义思想铸魂育人，推动思政课建设与党的创新理论武装同步推进。","explanation":"第69题要求选出错误表述。A项写对了“立德树人根本任务”，但把文章中铸魂育人所用的“新时代中国特色社会主义思想”换成了“马克思主义思想”，因此应选A。","references":[],"evidence":"实施新时代立德树人工程，坚持思政课建设与党的创新理论","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"f38d8f67c27bf86e","label":"新时代立德树人工程","topic":"年度政府工作","category":"时政","text":"1.新时代立德树人工程\n实施新时代立德树人工程，促进思政课堂和社会课堂有效融合，加强体育、美育、劳动\n教育，完善教育评价体系。\n——《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》\n要坚定不移落实好立德树人根本任务。坚持不懈用新时代中国特色社会主义思想铸魂育\n人，实施新时代立德树人工程，坚持思政课建设与党的创新理论武装同步推进。加强党的创\n新理论体系化学理化研究阐释，构建以各学科标识性概念、原创性理论为主干的中国哲学社\n会科学自主知识体系。不断拓展实践育人和网络育人的空间和阵地。\n——《求是》杂志文章《加快建设教育强国》","source":{"doc":"6cbfb01fe723bba64b75","first":41,"last":41,"page":41,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#69":{"paper":"政治理论必刷100题","n":69,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",21],"asrc":["国省考政治理论必刷100题.pdf",76],"card":"39b266ed8b391654d9800a11","links":[{"id":"k-b04cf0c4881c60de","role":"直接考查","why":"落实立德树人根本任务要求坚持用新时代中国特色社会主义思想铸魂育人。"}]}},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-b04cf0c4881c60de":[["政治理论必刷100题#69"]]}};
